import json, time
from http.server import BaseHTTPRequestHandler, HTTPServer
class H(BaseHTTPRequestHandler):
    def do_POST(self):
        n = int(self.headers.get("content-length") or 0)
        body = self.rfile.read(n)
        try:
            d = json.loads(body)
            alerts = [{"alertname": a.get("labels", {}).get("alertname"), "severity": a.get("labels", {}).get("severity"),
                       "status": a.get("status"), "summary": a.get("annotations", {}).get("summary")} for a in d.get("alerts", [])]
            line = {"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "path": self.path, "receiver": d.get("receiver"),
                    "status": d.get("status"), "alerts": alerts}
        except Exception as e:
            line = {"path": self.path, "error": str(e), "raw": body[:500].decode("utf-8", "replace")}
        print(json.dumps(line), flush=True)
        self.send_response(200); self.end_headers(); self.wfile.write(b"ok")
    def do_GET(self):
        self.send_response(200); self.end_headers(); self.wfile.write(b"alert-sink ok\n")
    def log_message(self, *a): pass
HTTPServer(("", 8080), H).serve_forever()

